<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {loadPlatform} from '../platform'
import {apiRequest} from '@yunshu/shared/api'
const route=useRoute(), section=computed(()=>route.path.slice(1)), rows=ref<any[]>([]), data=ref<any>(null), error=ref(''), busy=ref(false), keyword=ref(''), page=ref(1), total=ref(0), options=ref<any[]>([]), groups=ref<any[]>([]), temporary=ref('')
const actionFilter=ref('')
const selected=ref<number[]>([]), detail=ref<any>(null), roleFilter=ref(''), statusFilter=ref(''), start=ref(''), end=ref('')
const base='/api/v1/admin/system/'
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'请求失败'}finally{busy.value=false}}
function query(){const q=new URLSearchParams({keyword:keyword.value,page:String(page.value)});if(section.value==='users'){if(roleFilter.value)q.set('role_id',roleFilter.value);if(statusFilter.value)q.set('enabled',statusFilter.value)}else{if(actionFilter.value)q.set('action',actionFilter.value);if(start.value)q.set('start',new Date(start.value).toISOString());if(end.value)q.set('end',new Date(end.value).toISOString())}return q}
async function batch(action:string){if(!selected.value.length||!confirm('确定批量操作所选用户？'))return;await run(async()=>{await apiRequest(base+'user-batches',{method:'POST',body:JSON.stringify({ids:selected.value,action})});selected.value=[]});if(!error.value)await load()}
async function show(id:number){await run(async()=>{detail.value=await apiRequest(base+section.value+'/'+id)})}
async function load(){await run(async()=>{data.value=null;if(section.value==='settings'){data.value=await apiRequest(base+'settings');return}if(section.value==='roles'){rows.value=await apiRequest<any[]>(base+'roles');groups.value=await apiRequest<any[]>(base+'permissions')}else{const result=await apiRequest<any>(base+section.value+'?'+query());rows.value=result.items;total.value=result.total;if(section.value==='users')options.value=await apiRequest<any[]>(base+'role-options')}})}
watch(section,()=>{page.value=1;keyword.value='';void load()},{immediate:true})
function edit(row?:any){data.value=section.value==='roles'?{...(row||{name:'',code:'',description:'',permissions:[]}),permissions:[...(row?.permissions||[])]}:{...(row||{username:'',phone:'',email:'',role_id:options.value.find(r=>r.code!=='super_admin')?.id,enabled:true}),password:'',enabled:row?Boolean(row.enabled):true}}
async function save(){await run(async()=>{const d=data.value;const body=section.value==='roles'?{name:d.name,code:d.code,description:d.description,permissions:d.permissions,version:d.version}:section.value==='users'?{username:d.username,phone:d.phone,email:d.email,role_id:Number(d.role_id),enabled:Boolean(d.enabled),password:d.password||undefined,version:d.version}:{name:d.name,description:d.description,logo_file_id:d.logo_file_id,avatar_file_id:d.avatar_file_id,version:d.version};await apiRequest(base+section.value+(section.value!=='settings'&&d.id?'/'+d.id:''),{method:section.value==='settings'||d.id?'PUT':'POST',body:JSON.stringify(body)});data.value=null;await loadPlatform()});if(!error.value)await load()}
async function action(row:any,act:string){if(!confirm('确定执行此操作？'))return;await run(async()=>{if(section.value==='roles')await apiRequest(base+'roles/'+row.id,{method:'DELETE'});else if(act==='reset'){const result=await apiRequest<any>(base+'users/'+row.id+'/password-resets',{method:'POST'});temporary.value=result.temporary_password}else await apiRequest(base+'user-batches',{method:'POST',body:JSON.stringify({ids:[row.id],action:act})})});if(!error.value)await load()}
async function upload(e:Event,key:string){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;await run(async()=>{const r=await fetch(base+'files',{method:'POST',headers:{'X-Requested-With':'XMLHttpRequest'},body:f});const result=await r.json();if(!r.ok)throw Error(result.message);data.value[key]=result.data.id})}
async function exportLogs(){await run(async()=>{const r=await fetch(base+'log-exports?'+query(),{method:'POST',headers:{'X-Requested-With':'XMLHttpRequest'}});if(!r.ok)throw Error((await r.json()).message);const url=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=url;a.download='operation-logs.csv';a.click();URL.revokeObjectURL(url)})}
</script>
<template><section class="system-panel"><header><h2>{{route.meta.title}}</h2><button :disabled="busy" @click="load">刷新</button><button v-if="['users','roles'].includes(section)" @click="edit()">新增</button><button v-if="section==='logs'" @click="exportLogs">导出 CSV</button></header><p v-if="error" role="alert">{{error}}</p><form v-if="['users','logs'].includes(section)" @submit.prevent="page=1;load()"><input v-model="keyword" placeholder="搜索关键词"><template v-if="section==='users'"><select v-model="roleFilter"><option value="">全部角色</option><option v-for="r in options" :value="r.id">{{r.name}}</option></select><select v-model="statusFilter"><option value="">全部状态</option><option value="1">启用</option><option value="0">禁用</option></select></template><template v-else><select v-model="actionFilter"><option value="">全部操作</option><option value="auth.login">登录</option><option value="auth.logout">退出</option><option value="user.">用户操作</option><option value="role.">角色操作</option><option value="settings.">设置</option><option value="file.">上传</option><option value="log.export">导出</option></select><input v-model="start" type="datetime-local" aria-label="开始时间"><input v-model="end" type="datetime-local" aria-label="结束时间"></template><button :disabled="busy">查询</button></form>
<div v-if="section==='users'"><button :disabled="busy||!selected.length" @click="batch('enable')">批量启用</button><button :disabled="busy||!selected.length" @click="batch('disable')">批量禁用</button><button :disabled="busy||!selected.length" @click="batch('delete')">批量删除</button></div><div class="table-wrap" v-if="section!=='settings'"><table><thead><tr><th v-for="label in section==='users'?['用户名','手机号','角色','状态','操作']:section==='roles'?['角色','编码','描述','用户数','操作']:['用户','操作','目标','IP','结果','时间']">{{label}}</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><template v-if="section==='users'"><td><input v-model="selected" type="checkbox" :value="r.id" :disabled="Boolean(r.is_super)"><button @click="show(r.id)">{{r.username}}</button></td><td>{{r.phone||'—'}}</td><td>{{r.role_name}}</td><td>{{r.enabled?'启用':'禁用'}}</td><td><template v-if="!r.is_super"><button @click="edit(r)">编辑</button><button @click="action(r,r.enabled?'disable':'enable')">{{r.enabled?'禁用':'启用'}}</button><button @click="action(r,'reset')">重置密码</button><button @click="action(r,'delete')">删除</button></template><span v-else>内置保护</span></td></template><template v-else-if="section==='roles'"><td>{{r.name}}</td><td>{{r.code}}</td><td>{{r.description}}</td><td>{{r.user_count}}</td><td><button :disabled="r.code==='super_admin'" @click="edit(r)">编辑权限</button><button :disabled="Boolean(r.built_in||r.user_count)" @click="action(r,'delete')">删除</button></td></template><template v-else><td><button @click="show(r.id)">{{r.actor_name}}</button></td><td>{{r.action}}</td><td>{{r.target}}</td><td>{{r.ip}}</td><td>{{r.outcome}}</td><td>{{new Date(r.created_at).toLocaleString()}}</td></template></tr></tbody></table><p v-if="!rows.length">暂无匹配记录</p></div>
<footer v-if="['users','logs'].includes(section)">共 {{total}} 条 <button :disabled="page<=1||busy" @click="page--;load()">上一页</button> 第 {{page}} 页 <button :disabled="page*20>=total||busy" @click="page++;load()">下一页</button></footer>
<form v-if="data" class="editor" @submit.prevent="save"><h3>{{section==='settings'?'基本信息设置':'编辑资料'}}</h3><template v-if="section==='roles'"><label>名称<input v-model="data.name" required maxlength="64"></label><label>编码<input v-model="data.code" required :disabled="Boolean(data.built_in)"></label><label>描述<input v-model="data.description" maxlength="500"></label><fieldset v-for="g in groups"><legend>{{g.name}}</legend><label v-for="p in g.items" class="check"><input v-model="data.permissions" type="checkbox" :value="p.key" :disabled="p.key==='system:roles'">{{p.label}}</label></fieldset></template>
<template v-else-if="section==='users'"><label>用户名<input v-model="data.username" required maxlength="64"></label><label>手机号<input v-model="data.phone" required maxlength="32"></label><label>邮箱<input v-model="data.email" type="email"></label><label>角色<select v-model="data.role_id" required><option v-for="r in options.filter(x=>x.code!=='super_admin')" :value="r.id">{{r.name}}</option></select></label><label>密码（编辑时留空不修改）<input v-model="data.password" type="password" :required="!data.id" minlength="8" maxlength="128" autocomplete="new-password"></label><label class="check"><input v-model="data.enabled" type="checkbox" :true-value="true" :false-value="false">启用</label></template>
<template v-else><label>平台名称<input v-model="data.name" required maxlength="64"></label><label>平台描述<textarea v-model="data.description" maxlength="1000"></textarea></label><label v-for="(label,key) in {logo_file_id:'Logo',avatar_file_id:'默认头像'}">{{label}}<img v-if="data[key]" :src="base+'files/'+data[key]"><input type="file" accept="image/png,image/jpeg,image/webp" @change="upload($event,key)"><button type="button" @click="data[key]=null">使用默认图案</button></label><button type="button" @click="data.name='云枢智学';data.description='让学习更有章法，让成长清晰可见。';data.logo_file_id=null;data.avatar_file_id=null">恢复默认值</button><small>支持 PNG/JPEG/WebP，最大2MB、2048像素。</small></template><div><button type="button" @click="section==='settings'?load():data=null">取消</button><button :disabled="busy">保存</button></div></form><aside v-if="detail"><h3>详情</h3><pre style="white-space:pre-wrap">{{detail}}</pre><button @click="detail=null">关闭</button></aside><aside v-if="temporary"><h3>一次性临时密码（仅显示本次）</h3><code>{{temporary}}</code><p>有效24小时，登录后必须改密。请通过可信渠道交付。</p><button @click="temporary=''">已记录，关闭</button></aside></section></template>
<style scoped>.system-panel{background:#fff;border:1px solid #e6e8f0;border-radius:12px;padding:28px}header,footer{display:flex;align-items:center;gap:14px;margin-bottom:24px}h2{flex:1;font-size:20px}button{padding:8px 12px;border:1px solid #dedfea;border-radius:6px;color:#6262a4;background:white;cursor:pointer}button:disabled{opacity:.4;cursor:default}input,select,textarea{padding:10px;border:1px solid #dfe1eb;border-radius:6px;font:inherit}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:14px}.table-wrap{overflow:auto;margin:24px 0}td,th{padding:14px;text-align:left;border-bottom:1px solid #eceef5}th{background:#f7f8fc}td button{border:0;padding:5px}.editor{display:grid;gap:18px;max-width:700px;margin-top:24px;padding:24px;border:1px solid #e6e7f0;border-radius:10px}label{display:grid;gap:8px}.check{display:inline-flex;align-items:center;margin:5px 12px 5px 0}img{width:64px;height:64px;object-fit:contain}[role=alert]{color:#b33043}aside{background:#fff8e6;padding:20px;margin-top:20px}code{font-size:20px;user-select:all}fieldset{border:1px solid #e6e7ee}</style>
